using System.Globalization;
using System.Reflection;

namespace D47.Core.Knowledge;

/// <summary>The shipped table of material traders by station, generated by <c>tools/gen-material-traders.py</c>.</summary>
public static class MaterialTraderTable
{
    private const string ResourceName = "D47.Core.MaterialTraders";

    private static readonly Lazy<IReadOnlyDictionary<long, string>> Loaded =
        new(() => Read(typeof(MaterialTraderTable).GetTypeInfo().Assembly.GetManifestResourceStream(ResourceName)),
            LazyThreadSafetyMode.ExecutionAndPublication);

    /// <summary>Every listed station's MarketID and trader type.</summary>
    public static IReadOnlyDictionary<long, string> All => Loaded.Value;

    /// <summary>The trader type at this station, spelt as in <see cref="StationQuery.TraderTypes"/>, or null when it is not listed.</summary>
    public static string? TypeOf(long marketId) =>
        Loaded.Value.TryGetValue(marketId, out var type) ? type : null;

    private static IReadOnlyDictionary<long, string> Read(Stream? stream)
    {
        if (stream is null)
        {
            return new Dictionary<long, string>();
        }

        using (stream)
        using (var reader = new StreamReader(stream))
        {
            return Read(reader);
        }
    }

    internal static IReadOnlyDictionary<long, string> Read(TextReader reader)
    {
        var types = new Dictionary<long, string>();
        var header = true;

        while (reader.ReadLine() is { } line)
        {
            if (line.Length == 0 || line[0] == '#')
            {
                continue;
            }

            if (header)
            {
                header = false;
                continue;
            }

            var columns = line.Split('\t');
            if (columns.Length >= 2 && long.TryParse(columns[0], NumberStyles.None, CultureInfo.InvariantCulture, out var marketId))
            {
                types[marketId] = columns[1];
            }
        }

        return types;
    }
}
